import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"The catalog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/catalog.md","filePath":"guide/catalog.md"}'),r={name:"guide/catalog.md"};function d(i,t,n,h,l,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="the-catalog" tabindex="-1">The catalog <a class="header-anchor" href="#the-catalog" aria-label="Permalink to &quot;The catalog&quot;">​</a></h1><p><strong>New project → Catalog</strong> lists applications that install in one step: Orbit creates the project, the databases the application needs with daily backups, and the application itself, already configured to use them. Each entry pins an image version, so what you install today is what you get, and the project offers the update when the catalog moves.</p><h2 id="entries" tabindex="-1">What is in it <a class="header-anchor" href="#entries" aria-label="Permalink to &quot;What is in it {#entries}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>What it is</th><th>Database</th><th>First sign-in</th></tr></thead><tbody><tr><td>n8n</td><td>Workflow automation</td><td>PostgreSQL</td><td>The first visit creates the owner account</td></tr><tr><td>Umami</td><td>Website analytics</td><td>PostgreSQL</td><td><code>admin</code> / <code>umami</code>, change it right away</td></tr><tr><td>Metabase</td><td>Dashboards over your databases</td><td>PostgreSQL</td><td>Setup on the first visit</td></tr><tr><td>Grafana</td><td>Dashboards and alerts</td><td>PostgreSQL</td><td><code>admin</code> and the generated password</td></tr><tr><td>Directus</td><td>Headless CMS and admin panel</td><td>PostgreSQL</td><td>Your email and the generated password</td></tr><tr><td>Wiki.js</td><td>A wiki</td><td>PostgreSQL</td><td>Setup on the first visit</td></tr><tr><td>Miniflux</td><td>Feed reader</td><td>PostgreSQL</td><td><code>admin</code> and the generated password</td></tr><tr><td>Shlink</td><td>URL shortener</td><td>PostgreSQL</td><td>The generated API key</td></tr><tr><td>linkding</td><td>Bookmarks</td><td>PostgreSQL</td><td><code>admin</code> and the generated password</td></tr><tr><td>Vaultwarden</td><td>Bitwarden-compatible password server</td><td>PostgreSQL</td><td>Create your account on the first visit; the admin page uses the generated token</td></tr><tr><td>IT-Tools</td><td>Developer tools</td><td>none</td><td>nothing to configure</td></tr></tbody></table><h2 id="install" tabindex="-1">What installing does <a class="header-anchor" href="#install" aria-label="Permalink to &quot;What installing does {#install}&quot;">​</a></h2><ol><li><strong>Review.</strong> The entry&#39;s page lists what Orbit creates: the application with its image, port, health check and resources, each database with its size and backup schedule, and every variable with where its value comes from. Secrets are generated in your browser; the ones you need to sign in are shown once, with a copy button. Regenerate them before installing if you prefer.</li><li><strong>Create.</strong> Orbit creates the project, then the databases, then the application, the same way the <a href="./compose">Compose import</a> does. Database variables are references, resolved at deploy time, so rotating a database&#39;s credentials later keeps working.</li><li><strong>Address.</strong> Variables that need the application&#39;s own address, such as <code>WEBHOOK_URL</code> or <code>PUBLIC_URL</code>, cannot be known before the application exists. Orbit sets them from the generated address after the first deployment and deploys again. Add your own domain afterwards under <strong>Domains</strong>, then update those variables to it.</li></ol><p>The result is an ordinary project: deployments, logs, variables, backups and the terminal all work as for anything else.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates {#updates}&quot;">​</a></h2><p>A project remembers the entry and version it came from. When the catalog carries a newer version, the project&#39;s overview says so and <strong>Review the update</strong> shows what would change: the new image tag, and any variables the entry gained since, with where their values come from. Applying it deploys the new image, adds the variables and records the new version. If the application&#39;s image no longer comes from the entry&#39;s repository, the image is left alone.</p><p>Entries only move forward in the catalog that ships with your Orbit; <a href="./updates">updating Orbit</a> brings the newer catalog.</p><h2 id="not-yet" tabindex="-1">What is not in it yet <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;What is not in it yet {#not-yet}&quot;">​</a></h2><p>Applications run without persistent volumes on Orbit, so the catalog holds applications whose state fits in a managed database. Uploaded files stay in the container and are lost on the next deployment unless the application can use a <a href="./spaces">Space</a>. That keeps a few popular ones out for now:</p><ul><li><strong>Plausible</strong> needs ClickHouse, which Orbit does not manage.</li><li><strong>Uptime Kuma</strong> keeps its data in SQLite on a volume.</li><li><strong>Ghost</strong> keeps uploaded images on a volume.</li></ul>',13)])])}const u=e(r,[["render",d]]);export{g as __pageData,u as default};
